# Use colour only for interactive terminals. NO_COLOR always wins.
if [ -t 1 ] && [ -z "${NO_COLOR+x}" ] && [ "${TERM:-dumb}" != "dumb" ]; then
    esc=$(printf '\033')
    BOLD="${esc}[1m"
    DIM="${esc}[2m"
    GREEN="${esc}[32m"
    RED="${esc}[31m"
    YELLOW="${esc}[33m"
    CYAN="${esc}[36m"
    RESET="${esc}[0m"
else
    BOLD=''
    DIM=''
    GREEN=''
    RED=''
    YELLOW=''
    CYAN=''
    RESET=''
fi

ok_line() { printf '%s[ OK ]%s %s\n' "$GREEN" "$RESET" "$*"; }
fail_line() { printf '%s[FAIL]%s %s\n' "$RED" "$RESET" "$*" >&2; }
warn_line() { printf '%s[WARN]%s %s\n' "$YELLOW" "$RESET" "$*" >&2; }
step() { printf '  %s->%s %s\n' "$CYAN" "$RESET" "$*"; }
detail() { printf '     %s\n' "$*"; }

usage() {
    cat <<'WGMESHWIZARD_USAGE'
Usage: ./deploy.sh [options]

Options:
  --dry-run       Show what would be done without changing hosts
  --apply-hosts   Apply the embedded hosts block to /etc/hosts
  --no-hosts      Do not modify /etc/hosts
  --no-install    Do not install missing wireguard-tools
  --fail-fast     Stop after the first failed host
  -h, --help      Show this help

Environment:
  NO_COLOR        Disable coloured output
WGMESHWIZARD_USAGE
}

while [ $# -gt 0 ]; do
    case "$1" in
        --dry-run) DRY_RUN=1 ;;
        --apply-hosts)
            if [ "$HOSTS_AVAILABLE" -eq 1 ]; then
                APPLY_HOSTS=1
            else
                warn_line "--apply-hosts was given, but this mesh has no generated hosts block."
                APPLY_HOSTS=0
            fi
            ;;
        --no-hosts) APPLY_HOSTS=0 ;;
        --no-install) INSTALL_MISSING=0 ;;
        --fail-fast) KEEP_GOING=0 ;;
        -h | --help)
            usage
            exit 0
            ;;
        *)
            fail_line "Unknown option: $1"
            usage >&2
            exit 2
            ;;
    esac
    shift
done

if [ "$HOSTS_AVAILABLE" -eq 0 ]; then
    APPLY_HOSTS=0
fi

ssh_target=
ssh_port=
remote() {
    if [ -n "$ssh_port" ]; then
        ssh -o ConnectTimeout=10 -p "$ssh_port" "$ssh_target" "$@"
    else
        ssh -o ConnectTimeout=10 "$ssh_target" "$@"
    fi
}

ensure_wireguard_tools() {
    if [ "$INSTALL_MISSING" -eq 0 ]; then
        remote '
            if ! command -v wg-quick >/dev/null 2>&1; then
                echo "wg-quick is not installed (--no-install was given)" >&2
                exit 1
            fi
            if ! command -v systemctl >/dev/null 2>&1; then
                echo "systemd is not available" >&2
                exit 1
            fi
        '
        return
    fi

    remote sh -s <<'WGMESHWIZARD_ENSURE'
set -eu
if ! command -v systemctl >/dev/null 2>&1; then
    echo "systemd is required on this host" >&2
    exit 1
fi
if command -v wg-quick >/dev/null 2>&1; then
    exit 0
fi
if [ "$(id -u)" -eq 0 ]; then
    SUDO=""
elif command -v sudo >/dev/null 2>&1; then
    SUDO="sudo"
else
    echo "need root or sudo to install wireguard-tools" >&2
    exit 1
fi
if command -v apt-get >/dev/null 2>&1; then
    export DEBIAN_FRONTEND=noninteractive
    $SUDO apt-get update
    $SUDO apt-get install -y wireguard-tools
elif command -v dnf >/dev/null 2>&1; then
    $SUDO dnf install -y wireguard-tools
elif command -v yum >/dev/null 2>&1; then
    $SUDO yum install -y wireguard-tools
elif command -v pacman >/dev/null 2>&1; then
    $SUDO pacman -Sy --noconfirm wireguard-tools
elif command -v zypper >/dev/null 2>&1; then
    $SUDO zypper --non-interactive install wireguard-tools
elif command -v emerge >/dev/null 2>&1; then
    $SUDO emerge --ask=n --oneshot wireguard-tools
elif command -v apk >/dev/null 2>&1; then
    $SUDO apk add --no-cache wireguard-tools
else
    echo "no supported package manager found; install wireguard-tools manually or use --no-install" >&2
    exit 1
fi
command -v wg-quick >/dev/null 2>&1 || {
    echo "wireguard-tools installation did not provide wg-quick" >&2
    exit 1
}
WGMESHWIZARD_ENSURE
}

install_config() {
    remote sh -s -- "$1" "$2" <<'WGMESHWIZARD_INSTALL'
set -eu
tmp=$1
dest=$2
cleanup() { rm -f "$tmp"; }
trap cleanup EXIT HUP INT TERM
if [ "$(id -u)" -eq 0 ]; then
    install -d -m 700 /etc/wireguard
    install -m 600 "$tmp" "$dest"
elif command -v sudo >/dev/null 2>&1; then
    sudo sh -c 'install -d -m 700 /etc/wireguard && install -m 600 "$1" "$2"' sh "$tmp" "$dest"
else
    echo "need root or sudo to write $dest" >&2
    exit 1
fi
WGMESHWIZARD_INSTALL
}

enable_service() {
    remote sh -s -- "$1" <<'WGMESHWIZARD_SERVICE'
set -eu
unit=$1
if [ "$(id -u)" -eq 0 ]; then
    systemctl daemon-reload || true
    systemctl enable "$unit"
    systemctl restart "$unit"
elif command -v sudo >/dev/null 2>&1; then
    sudo sh -c 'systemctl daemon-reload || true; systemctl enable "$1" && systemctl restart "$1"' sh "$unit"
else
    echo "need root or sudo to manage $unit" >&2
    exit 1
fi
WGMESHWIZARD_SERVICE
}

apply_hosts() {
    if [ "$APPLY_HOSTS" -ne 1 ]; then
        return 0
    fi

    hosts_file=$(mktemp "${TMPDIR:-/tmp}/wgmw-hosts.XXXXXX") || return 1
    trap 'rm -f "$hosts_file"' EXIT HUP INT TERM
    printf '%s' "$HOSTS_BLOCK" > "$hosts_file" || return 1

    remote_tmp=/tmp/wgmeshwizard-hosts-$$.txt
    if ! remote "umask 077; cat > '$remote_tmp'" < "$hosts_file"; then
        return 1
    fi

    remote sh -s -- "$remote_tmp" <<'WGMESHWIZARD_APPLY_HOSTS'
set -eu
src=$1
tmp=
cleanup() {
    rm -f "$src"
    if [ -n "$tmp" ]; then
        rm -f "$tmp"
    fi
}
trap cleanup EXIT HUP INT TERM

if [ "$(id -u)" -eq 0 ]; then
    SUDO=
elif command -v sudo >/dev/null 2>&1; then
    SUDO=sudo
else
    echo "need root or sudo to update /etc/hosts" >&2
    exit 1
fi

tmp=$(mktemp) || exit 1
awk '
    BEGIN { skipping = 0 }
    /^### BEGIN WGMESHWIZARD HOSTS###$/ { skipping = 1; next }
    /^### END WGMESHWIZARD HOSTS###$/ { skipping = 0; next }
    !skipping { lines[++count] = $0 }
    END {
        last = count
        while (last > 0 && lines[last] == "") last--
        for (i = 1; i <= last; i++) print lines[i]
    }
' /etc/hosts > "$tmp"

{
    printf '\n### BEGIN WGMESHWIZARD HOSTS###\n'
    cat "$src"
    last_byte=$(tail -c 1 "$src" 2>/dev/null || true)
    if [ -n "$last_byte" ]; then
        printf '\n'
    fi
    printf '### END WGMESHWIZARD HOSTS###\n'
} >> "$tmp"

if [ -n "$SUDO" ]; then
    $SUDO sh -c 'install -m 644 "$1" /etc/hosts' sh "$tmp"
else
    install -m 644 "$tmp" /etc/hosts
fi
WGMESHWIZARD_APPLY_HOSTS
}

deploy_host() (
    index=$1
    name=$2
    ssh_target=$3
    ssh_port=$4
    tunnel=$5

    printf '\n%s[%s/%s]%s %s\n' "$BOLD" "$index" "$TOTAL_HOSTS" "$RESET" "$name"

    if [ -z "$ssh_target" ]; then
        printf '  %sNo SSH target configured.%s Set Endpoint or SSHTarget for this host.\n' "$RED" "$RESET" >&2
        exit 1
    fi

    if [ -n "$ssh_port" ]; then
        detail "target: $ssh_target:$ssh_port"
    else
        detail "target: $ssh_target"
    fi
    detail "tunnel: $tunnel (wg-quick@$tunnel.service)"

    config=$(mktemp "${TMPDIR:-/tmp}/wgmw-conf.XXXXXX") || {
        printf '  %sCould not create a temporary config file.%s\n' "$RED" "$RESET" >&2
        exit 1
    }
    trap 'rm -f "$config"' EXIT HUP INT TERM
    cat > "$config" || {
        printf '  %sCould not read the embedded config.%s\n' "$RED" "$RESET" >&2
        exit 1
    }

    if [ "$DRY_RUN" -eq 1 ]; then
        step "Dry run: no changes will be made"
        detail "would install /etc/wireguard/$tunnel.conf"
        detail "would enable and restart wg-quick@$tunnel.service"
        if [ "$APPLY_HOSTS" -eq 1 ]; then
            detail "would apply the WGMESHWIZARD hosts block to /etc/hosts"
        fi
        exit 0
    fi

    step "Checking wireguard-tools and systemd"
    if ! ensure_wireguard_tools; then
        printf '  %sCould not prepare WireGuard on this host.%s\n' "$RED" "$RESET" >&2
        exit 1
    fi

    remote_tmp=/tmp/wgmeshwizard-${tunnel}-$$.conf
    step "Uploading configuration"
    if ! remote "umask 077; cat > '$remote_tmp'" < "$config"; then
        printf '  %sCould not upload the configuration to %s.%s\n' "$RED" "$RESET" "$remote_tmp" >&2
        exit 1
    fi

    step "Installing /etc/wireguard/$tunnel.conf"
    if ! install_config "$remote_tmp" "/etc/wireguard/$tunnel.conf"; then
        printf '  %sCould not install /etc/wireguard/%s.conf.%s\n' "$RED" "$RESET" "$tunnel" >&2
        exit 1
    fi

    step "Enabling and restarting wg-quick@$tunnel.service"
    if ! enable_service "wg-quick@$tunnel.service"; then
        printf '  %sCould not enable or restart wg-quick@%s.service.%s\n' "$RED" "$RESET" "$tunnel" >&2
        exit 1
    fi

    if [ "$APPLY_HOSTS" -eq 1 ]; then
        step "Updating /etc/hosts"
        if ! apply_hosts; then
            printf '  %sCould not update /etc/hosts.%s\n' "$RED" "$RESET" >&2
            exit 1
        fi
    fi
)

