WGMESHWIZARD_CONFIG_8
status=$?
if [ "$status" -eq 0 ]; then
deployed=$((deployed + 1))
if [ "$DRY_RUN" -eq 1 ]; then
ok_line "$host_name (dry run)"
else
ok_line "$host_name"
fi
else
failed=$((failed + 1))
if [ -z "$failed_hosts" ]; then
failed_hosts=$host_name
else
failed_hosts="$failed_hosts, $host_name"
fi
fail_line "$host_name"
if [ "$KEEP_GOING" -eq 0 ]; then
printf '\n%s[FAIL]%s Stopping after the first failure (--fail-fast).\n' "$RED" "$RESET" >&2
stopped=1
fi
fi
fi

printf '\n%sDeployment summary%s\n' "$BOLD" "$RESET"
if [ "$DRY_RUN" -eq 1 ]; then
printf '  %s[ OK ]%s %d host(s) checked\n' "$GREEN" "$RESET" "$deployed"
else
printf '  %s[ OK ]%s %d host(s) succeeded\n' "$GREEN" "$RESET" "$deployed"
fi
if [ "$failed" -ne 0 ]; then
printf '  %s[FAIL]%s %d host(s) failed: %s\n' "$RED" "$RESET" "$failed" "$failed_hosts" >&2
fi
if [ "$attempted" -lt "$TOTAL_HOSTS" ]; then
printf '  %s[SKIP]%s %d host(s) not attempted\n' "$YELLOW" "$RESET" "$((TOTAL_HOSTS - attempted))" >&2
fi
if [ "$failed" -ne 0 ]; then
exit 1
fi
if [ "$DRY_RUN" -eq 1 ]; then
printf '%s[ OK ]%s Dry run complete. No changes were made.\n' "$GREEN" "$RESET"
else
printf '%s[ OK ]%s Deployment complete.\n' "$GREEN" "$RESET"
fi
